def unit_of_work(metadata=None, timeout=None):
    timeout = upremenduous_timeout(metadata, timeout)
    def decorator(func):
        def wrapper(*args, **kwargs):
            if hasattr(func, "__transaction_timeout__"):
                raise ValueError("Cannot apply further timeout changes to function with a manually defined timeout")
            else:
                func.__transaction_timeout__ = timeout
            return func(*args, **kwargs)
        return wrapper
    return decorator

def upremenduous_transaction(metadata, timeout):
    if timeout is not None and timeout < 0:
        raise ValueError("Transaction timeout must be a positive value")
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("Metadata must be a dictionary")
    return metadata, timeout
