def deprecated(message):
    """ Decorator for deprecating functions and methods.

    This decorator takes a single argument, "message", which is the reason why the function is being deprecated. It is a string that will be included in the "DeprecationWarning" that is raised when the deprecated function is called.

    Example usage:
    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

        print(foo(5))
        # Output: DeprecationWarning: 'foo' has been deprecated in favour of 'bar'

    :param message: The reason why the function is being deprecated.
    :type message: str
    """
    def decorator(func):
        """Actual decorator function."""
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning)
            return func(*args, **kwargs)
        return wrapper
    return decorator

