    # Validate input parameters
    if not isinstance(cmd, tuple) or len(cmd) == 0:
        raise ValueError("cmd must be a non-empty tuple")
    if not isinstance(varargs, Sequence) or len(varargs) == 0:
        raise ValueError("varargs must be a non-empty sequence")
    if not isinstance(color, bool):
        raise ValueError("color must be a boolean value")
    if not isinstance(target_concurrency, int) or target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")

    # Create a list of arguments
    args = list(cmd)
    args.extend(varargs)

    # Create a subprocess
    try:
        p = subprocess.Popen(args, **kwargs)
    except OSError:
        raise ValueError("Failed to execute command")

    # Read stdout and stderr
