def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is valid
    if not isinstance(path, str):
        raise TypeError("Path must be string.")
    if not os.path.exists(path):
        raise ValueError("Path does not exist.")

    # Check for invalid characters in path
    if os.path.split(path)[0].lower() in OCFL_FORBIDDEN_CHARACTERS:
        raise ValueError("Path contains invalid characters.")

    # Check for forbidden file names
    if os.path.basename(path).lower() in OCFL_FORBIDDEN_FILENAMES:
        raise ValueError("File name contains invalid character.")

    # Check for prefix-suffix mapping
    prefix_suffix_map = self.prefix_suffix_map()
    if not prefix_suffix_map:
        raise ValueError("Prefix-suffix mapping is not set.")

    # Check for valid manifest
    manifest = self.load_filesystem_structure_and_fix_sizes(path)
    if not manifest:
        raise ValueError("Manifest is not valid.")

    # Validate prefix-suffix mapping
    for prefix, suffix in prefix_suffix_map.items():
        manifest_items = list(manifest.keys())
        if suffix not in manifest_items:
            raise ValueError(f"{suffix} is not found in manifest.")
        if prefix not in manifest_items:
            raise ValueError(f"{prefix} is not found in manifest.")
        if manifest[suffix] != manifest[prefix]:
            raise ValueError(f"{suffix} and {prefix} do not match.")

    # Validate structure
    root_dir, _ = os.path.split(path)
    top_manifest = self.load_filesystem_structure_and_fix_sizes(root_dir)
    if not top_manifest:
        raise ValueError("Top-level manifest is not valid.")
    if top_manifest != {}:
        raise ValueError("Top-level manifest is not empty.")

    return True

