def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if extract_spec_version:
            try:
                spec_version = int(inventory['type'])
                if not 1 <= spec_version <= 3:
                    raise ValueError("Invalid specification version: {}".format(spec_version))
            except (KeyError, ValueError):
                spec_version = self.spec_version
        else:
            spec_version = self.spec_version

        # validate structure
        if spec_version == 1:
            struct_el = inventory['struct_el']
            if not struct_el or not isinstance(struct_el,dict):
                raise ValueError("Invalid structure element")
            # validate each component
            for c in struct_el['components']:
                if not isinstance(c,dict):
                    raise ValueError("Invalid component")
                # validate name and role
                if not c['name'] or not isinstance(c['name'],str):
                    raise ValueError("Invalid name")
                if not c['role'] or not isinstance(c['role'],dict):
                    raise ValueError("Invalid role")
                # validate child components
                if 'components' in c and not isinstance(c['components'],list):
                    raise ValueError("Invalid components")

        elif spec_version == 2:
            struct_el = inventory['struct_el']
            if not struct_el or not isinstance(struct_el,dict):
                raise ValueError("Invalid structure element")
            # validate each component
            for c in struct_el['components']:
                if not isinstance(c,dict):
                    raise ValueError("Invalid component")
                # validate name and role
                if not c['name'] or not isinstance(c['name'],str):
                    raise ValueError("Invalid name")
                if not c['role'] or not isinstance(c['role'],dict):
                    raise ValueError("Invalid role")
                # validate child components
                if 'components' in c and not isinstance(c['components'],list):
                    raise ValueError("Invalid components")
                # validate type
                if not c['type'] or not isinstance(c['type'],str):
                    raise ValueError("Invalid type")
                # validate min_qty and max_qty
                min_qty = c['min_qty']
                max_qty = c['max_qty']
                if min_qty is None:
                    raise ValueError("min_qty not specified")
                if max_qty is None:
                    raise ValueError("max_qty not specified")
                if min_qty > max_qty:
                    raise ValueError("min_qty is greater than max_qty")
        else:
            raise ValueError("Unknown specification version: {}".format(spec_version))


        # validate relations
        relations = inventory['relations']
        if not isinstance(relations, list):
            raise ValueError("Invalid relations")
        for rel in relations:
            if not rel or not isinstance(rel, dict):
                raise ValueError("Invalid relation")
            # validate components
            components = rel['components']
            if not components or not isinstance(components, list):
                raise ValueError("Invalid components")
            for c in components:
                if not c or not isinstance(c, str):
                    raise ValueError("Invalid component")
            # validate type
            if not rel['type'] or not isinstance(rel['type'], str):
                raise ValueError("Invalid type")
            # validate label
            if not rel['label'] or not isinstance(rel['label'], str):
                raise ValueError("Invalid label")


        # validate spec version in the end
        if not str(spec_version) in inventory["type"]:
            raise ValueError("Incorrect type for spec version {}".format(spec_version))

