def pretty(self, indent=0, debug=False):
    indentation = '    ' * indent
    text = ''
    # obtain the relevant attributes of the current element
    attributes = self.attributes()
    # check if the element is a leaf element
    if len(attributes) == 0:
        text += indentation + self.tag + '\n'
    else:
        text += indentation + self.tag + '{\n'
        for attribute in attributes:
            text += indentation + attribute.pretty(indent + 1)
        text += indentation + '}'
    if debug: print(text)
    return text

