def find_path_type(path):
    # Initialize result to None
    result = None
    # Convert the path to a normalized absolute path
    abs_path = os.path.abspath(path)
    # Check if the path is an existing directory
    if os.path.isdir(abs_path):
        # Look for the "0=*" Namaste files
        namaste_files = [f for f in os.listdir(abs_path) if f.startswith("0=")]
        # Check if there are any Namaste files
        if len(namaste_files) > 0:
            # Look at the contents of the Namaste files to determine the directory type
            for namaste_file in namaste_files:
                with open(namaste_file, 'r') as f:
                    lines = f.readlines()
                    for line in lines:
                        # Check if the line starts with "0=" and ends with "T"
                        if line.startswith("0=") and line.endswith("T"):
                            # If the line is "0=C T", then the directory is an OCFL Storage Root
                            if line == "0=C T":
                                result = "root"
                            # If the line is "0=O T", then the directory is an OCFL Object
                            elif line == "0=O T":
                                result = "object"
                            # Otherwise, the directory is a file
                            else:
                                result = "file"
        else:
            # If there are not Namaste files, the directory is unknown
            result = "unknown"
    else:
        # If the path is not an existing directory, the path type is unknown
        result = "unknown"
    return result
