def deep_merge_nodes(nodes):
    keys = []
    for (key, value) in nodes:
        if isinstance(key, ruamel.yaml.nodes.ScalarNode):
            if key.value not in keys:
                keys.append(key.value)
            else:
                index = keys.index(key.value)
                nodes[index][1] = merge_nodes(nodes[index][1], value)
        else:
            raise ValueError("Invalid key type: " + type(key).__name__ + ". Only ScalarNodes are allowed as keys.")
    return nodes

def merge_nodes(node1, node2):
    if not isinstance(node1, ruamel.yaml.nodes.Node):
        raise ValueError("Invalid node1 type: " + type(node1).__name__ + ". Only Nodes can be merged.")
    if not isinstance(node2, ruamel.yaml.nodes.Node):
        raise ValueError("Invalid node2 type: " + type(node2).__name__ + ". Only Nodes can be merged.")

    if node1.tag == node2.tag:
        if node1.tag == ruamel.yaml.nodes.Node.SEQ_TAG:
            for item in node2.value:
                node1.value.append(item)
        elif node1.tag == ruamel.yaml.nodes.Node.MAP_TAG:
            for key, value in node2.value.items():
                node1.value[key] = value
    else:
        if node1.tag == ruamel.yaml.nodes.Node.SEQ_TAG and node2.tag == ruamel.yaml.nodes.Node.MAP_TAG:
            for key, value in node2.value.items():
                node1.value.append((key, value))
        elif node1.tag == ruamel.yaml.nodes.Node.MAP_TAG and node2.tag == ruamel.yaml.nodes.Node.SEQ_TAG:
            for item in node2.value:
                if isinstance(item, ruamel.yaml.nodes.Node):
                    node1.value[item.value] = item.value
                else:
                    node1.value[item] = node2.value[item]
        else:
            raise ValueError("Cannot merge nodes with tags " + node1.tag + " and " + node2.tag + ".")
    return node1
