def parse_subparser_arguments(unparsed_arguments, subparsers):
    # Initialize the return variables
    parsed_arguments = {}
    remaining_arguments = []

    # Iterate over the subparsers and provide each one with a chance to parse the arguments
    for subparser_name, subparser in subparsers.items():
        parser_args = unparsed_arguments
        known_args, parser_args = subparser.parse_known_args(parser_args)
        if known_args:
