def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
        if not os.path.exists(archive_path):
            raise ValueError("The specified archive path does not exist")
        if not os.path.isfile(archive_path):
            raise ValueError("The specified archive is not a file")

        if filename is None:
            filename = os.path.basename(archive_path)
        if not filename.endswith(".tar.gz"):
            raise ValueError("Filename must have .tar.gz extension")

        if not os.path.isdir(tmp_path):
            raise ValueError("Temporary path is not a directory")

        tmp_dir = os.path.join(tmp_path, filename.replace(".tar.gz", ""))
        if os.path.exists(tmp_dir):
            raise ValueError("Temporary path already exists")

        # extract the archive to the temporary directory
