def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks out of bounds")

    hour = int(ticks // 3600000000000)
    minute = int((ticks % 3600000000000) // 60000000000)
    second = int((ticks % 60000000000) // 1000000000)
    nanosecond = int(ticks % 1000000000)

