def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    replaced_text = text

    # Step through the text, keeping track of whether we're inside a code block
    for i, char in enumerate(text):
        if char == "`" and text[i-1] == "`":
            # Toggle the code block flag
            code_block = not code_block
        elif char == "<" and not code_block:
            # Found the start of a tag
            tag_start = i
            for j, char in enumerate(text[i:]):
                if char == ">":
                    # Found the end of the tag
                    tag = text[tag_start:tag_start+j]
                    tags.add(tag)
                    break

    # Optionally, replace the tags with the result of the replacer function
    if replacer:
        replaced_text = ""
        for i, char in enumerate(text):
            if char == "`" and text[i-1] == "`":
                # Toggle the code block flag
                code_block = not code_block
            elif char == "<" and not code_block:
                # Found the start of a tag
                tag_start = i
                for j, char in enumerate(text[i:]):
                    if char == ">":
                        # Found the end of the tag
                        tag = text[tag_start:tag_start+j]
                        replaced_text += replacer(tag)
                        break
            else:
                replaced_text += char

    return tags, replaced_text

