def parse_diaspora_webfinger_json(document: str) -> Dict:
    json_object = json.loads(document)
    parsed_webfinger = {}

    # Parse webfinger.signature.signed_time and
    # webfinger.signature.signature_value
    for signature in json_object["signature"]:
        if signature["auth"] == "diaspora+als":
            parsed_webfinger["signature_algorithm"] = signature["type"]
            parsed_webfinger["signature_string"] = signature["value"]
            break

    # Parse each element in the "rel" and "alias" array of the
    # "link" property of the webfinger dictionary
    for link in json_object["link"]:
        for rel in link["rel"]:
            if rel in parsed_webfinger["rels"]:
                parsed_webfinger["rels"][rel].append(link["href"])
            else:
                parsed_webfinger["rels"][rel] = [link["href"]]

        for alias in link["alias"]:
            if alias["identifier"] == "acct":
                parsed_webfinger["aliases"]["acct"] = alias["value"]
            if alias["identifier"] == "url":
                parsed_webfinger["aliases"]["url"] = alias["value"]

    return parsed_webfinger


def parse_diaspora_webfinger_xrd(document: str) -> Dict:
    xrd_object = xml.etree.ElementTree.fromstring(document)
    parsed_webfinger = {}

    # Parse webfinger.signature.signed_time and
    # webfinger.signature.signature_value
    signature_tag = xrd_object.find("Signature", namespaces=[NAMESPACE])
    for signature in signature_tag:
        if signature.attrib["auth"] == "diaspora+als":
            parsed_webfinger["signature_algorithm"] = signature.attrib["type"]
            parsed_webfinger["signature_string"] = signature.attrib["value"]
            break

    # Parse each element in the "link" array of the
    # webfinger dictionary
    for link in xrd_object.findall("Link", namespaces=[NAMESPACE]):
        for rel in link.attrib["rel"]:
            href = link.attrib["href"]
            if rel in parsed_webfinger["rels"]:
                parsed_webfinger["rels"][rel].append(href)
            else:
                parsed_webfinger["rels"][rel] = [href]

    return parsed_webfinger

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    webfinger = None

    try:
        webfinger_json = json.loads(document)
