def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    if not isinstance(ir_workspace, Workspace):
        raise ValueError("The 'ir_workspace' argument must be an Infrared Workspace object.")
    if not isinstance(ir_plugin, Plugin):
        raise ValueError("The 'ir_plugin' argument must be an Infrared Plugin object.")
    if not isinstance(playbook_path, str):
        raise ValueError("The 'playbook_path' argument must be a string.")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("The 'extra_vars' argument must be a dict or None.")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("The 'ansible_args' argument must be a dict or None.")

    ansible_args = ansible_args if ansible_args is not None else {}
    extra_vars = extra_vars if extra_vars is not None else {}

    process = Popen(['ansible-playbook', playbook_path] +
                    ['--extra-vars', "%s=%s" % (k, v) for k, v in extra_vars.items()] +
                    ['--ansible-args', "%s=%s" % (k, v) for k, v in ansible_args.items()],
                    stdout=PIPE, stderr=PIPE)

    try:
        output = process.communicate()[0]
    except ValueError as e:
        raise RuntimeError("An error occurred while running 'ansible-playbook: %s'." % e)

    return output.decode("utf-8")
